+	@SuppressWarnings("NullAway.Init")
+	private OptionSpec<String> version;
+
+	@SuppressWarnings("NullAway.Init")
+	private OptionSpec<String> name;
+
+	@SuppressWarnings("NullAway.Init")
+	private OptionSpec<String> description;
+
+	@SuppressWarnings("NullAway.Init")
+	private OptionSpec<String> packageName;
+
+	@SuppressWarnings("NullAway.Init")
